import sys
import re


def is_number(s):
    if not s:
        return False
    if s[0] == '-':
        s = s[1:]
    if '.' in s:
        parts = s.split('.')
        if len(parts) > 2:
            return False
        if not parts[1] or not parts[1].isdigit():
            return False
    if not s.isdigit():
        return False
    return True


def main():
    rows = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        cells = line.split("|")
        rows.append(cells)

    if not rows:
        return

    header_row = rows[0]
    data_rows = rows[1:]

    widths = [max(len(cell.strip()) for cell in column) for column in zip(*rows)]

    def fmt(row):
        cells = []
        for i, cell in enumerate(row):
            cell = cell.strip()
            width = widths[i] if i < len(widths) else 0
            if is_number(cell):
                cells.append(cell.rjust(width))
            else:
                cells.append(cell.ljust(width))
        return " | ".join(cells)

    print(fmt(header_row))
    print("-+-".join("-" * w for w in widths))
    for row in data_rows:
        print(fmt(row))


if __name__ == "__main__":
    main()
